def poisson_reconstruction(points: np.ndarray, depth: int = 10) -> trimesh.Trimesh:
    """Poisson surface reconstruction (requires Open3D)"""
    try:
        import open3d as o3d

        # Create point cloud
        pcd = o3d.geometry.PointCloud()
        pcd.points = o3d.utility.Vector3dVector(points)
        pcd.estimate_normals()

        # Poisson reconstruction with higher depth for better detail
        mesh, _ = o3d.geometry.TriangleMesh.create_from_point_cloud_poisson(
            pcd, depth=depth
        )

        # Convert to trimesh
        vertices = np.asarray(mesh.vertices)
        faces = np.asarray(mesh.triangles)
        return trimesh.Trimesh(vertices=vertices, faces=faces)

    except ImportError:
        print("Open3D not installed, using convex hull")
        return MeshReconstructor.convex_hull_mesh(points)

